package run.ikaros.password; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/password") public class PasswordVaultController{private final PasswordVaultService service;public PasswordVaultController(PasswordVaultService s){service=s;}@PostMapping("/vaults")public Mono<PasswordVaultView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@Valid@RequestBody CreatePasswordVaultRequest r){return service.create(a,r);}@GetMapping("/vaults")public Flux<PasswordVaultView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a){return service.list(a);}@PostMapping("/vaults/{id}/actions/unlock")public Mono<PasswordVaultView> unlock(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.setStatus(a,id,PasswordVaultStatus.UNLOCKED);}@PostMapping("/vaults/{id}/actions/lock")public Mono<PasswordVaultView> lock(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.setStatus(a,id,PasswordVaultStatus.LOCKED);}@PostMapping("/vaults/{vaultId}/items")public Mono<PasswordVaultItemView> item(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId,@Valid@RequestBody UpsertVaultItemRequest r){return service.createItem(a,vaultId,r);}@GetMapping("/vaults/{vaultId}/items")public Flux<PasswordVaultItemView> items(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID vaultId){return service.listItems(a,vaultId);}@PutMapping("/items/{id}")public Mono<PasswordVaultItemView> update(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id,@Valid@RequestBody UpsertVaultItemRequest r){return service.updateItem(a,id,r);}@DeleteMapping("/items/{id}")public Mono<PasswordVaultItemView> delete(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.deleteItem(a,id);}}
